+	// Build a set of existing device IDs.
+	HashSet<String> existing_device_ids;
+	for (int i = 0; i < server->feeds.size(); i++) {
+		Ref<CameraFeedWeb> feed = server->feeds[i];
+		if (feed.is_valid()) {
